@pytest.mark.parametrize("replacement", ["safe-public-ref", "wrong_alias", "same_alias"]) def test_every_stored_repeated_ref_must_match_its_typed_replacement( sbom_engine, sbom_api, replacement ): """仅新建合成历史坏行；合法重复引用仍200，错值固定503且不回显私有值。""" login, _ = sbom_api client, headers, _ = login() private = "https://synthetic_user:synthetic_password@example.test/sbom" raw = raw_document( { "bomFormat": "CycloneDX", "specVersion": "1.7", "components": [ {"type": "library", "name": "a", "bom-ref": private}, {"type": "library", "name": "b", "bom-ref": "public-b"}, {"type": "library", "name": "c", "bom-ref": "public-c"}, ], "dependencies": [{"ref": private, "dependsOn": ["public-b", "public-c"]}], } ) created = upload(client, headers, raw) assert created.status_code == 201 table = asset_snapshot_sbom_sidecars with sbom_engine.connect() as connection: snapshot = dict( connection.execute( select(asset_snapshots).where( asset_snapshots.c.snapshot_id == created.json()["snapshot"]["snapshot_id"] ) ) .mappings() .one() ) sidecar = dict( connection.execute(select(table).where(table.c.snapshot_id == snapshot["snapshot_id"])) .mappings() .one() ) snapshot.update( snapshot_id=str(uuid4()), snapshot_number=2, previous_snapshot_id=snapshot["snapshot_id"] ) snapshot["canonical_payload"].update(snapshot_id=snapshot["snapshot_id"], snapshot_number=2) sidecar["snapshot_id"] = snapshot["snapshot_id"] body = sidecar["canonical_payload"] body["snapshot_id"] = sidecar["snapshot_id"] alias = body["dependency_edges"][0]["source_ref"] body["dependency_edges"][1]["source_ref"] = { "same_alias": alias, "wrong_alias": "redacted-ref:" + "f" * 64, "safe-public-ref": "safe-public-ref", }[replacement] with sbom_engine.begin() as connection: connection.execute(insert(asset_snapshots).values(snapshot)) connection.execute(insert(table).values(sidecar)) response = client.get( f"/api/assets/{sidecar['asset_id']}/snapshots/{sidecar['snapshot_id']}/sbom" ) > assert response.status_code == (200 if replacement == "same_alias" else 503) E assert 200 == 503 E + where 200 = <Response [200 OK]>.status_code
